/// Board Evaluation - 棋盘评估函数
///
/// 职责：
/// - 评估棋盘局面优劣
/// - 为AI提供决策依据
library;

import '../engine/game_engine.dart';
import '../models/board_state.dart';
import '../models/piece_type.dart';
import '../models/position.dart';

/// 棋盘评估器
class BoardEvaluator {
  /// 评估棋盘局面
  ///
  /// 返回分数：
  /// - 正数表示传入 player 一方有优势
  /// - 负数表示其对手有优势
  /// - 0表示均势
  static int evaluate(BoardState board, PieceType player) {
    int score = 0;

    // 1. 棋子数量差异 (最重要)
    score += _evaluatePieceCount(board, player);

    // 2. 位置优势
    score += _evaluatePositions(board, player);

    // 3. 移动能力
    score += _evaluateMobility(board, player);

    // 4. 三子连线威胁（新增）
    score += _evaluateThreats(board, player);

    // 5. 防守价值（新增）
    score += _evaluateDefense(board, player);

    return score;
  }

  /// 评估棋子数量
  static int _evaluatePieceCount(BoardState board, PieceType player) {
    final isWhite = player == PieceType.white;
    final myCount =
        isWhite ? board.whitePieces.length : board.blackPieces.length;
    final oppCount =
        isWhite ? board.blackPieces.length : board.whitePieces.length;

    // 每个棋子价值1000分
    return (myCount - oppCount) * 1000;
  }

  /// 评估棋子位置
  static int _evaluatePositions(BoardState board, PieceType player) {
    int score = 0;
    final isWhite = player == PieceType.white;
    final myPieces = isWhite ? board.whitePieces : board.blackPieces;
    final opponentPieces = isWhite ? board.blackPieces : board.whitePieces;

    for (final pos in myPieces) {
      // 中心位置更有价值
      score += _getPositionValue(pos);
    }
    for (final pos in opponentPieces) {
      score -= _getPositionValue(pos);
    }

    return score;
  }

  /// 获取位置价值
  static int _getPositionValue(Position pos) {
    // 中心位置价值更高
    const centerPositions = [
      Position(1, 1),
      Position(1, 2),
      Position(2, 1),
      Position(2, 2),
    ];

    if (centerPositions.contains(pos)) {
      return 20;
    }
    return 10;
  }

  /// 评估移动能力
  static int _evaluateMobility(BoardState board, PieceType player) {
    final isWhite = player == PieceType.white;
    final myPieces = isWhite ? board.whitePieces : board.blackPieces;
    final opponentPieces = isWhite ? board.blackPieces : board.whitePieces;

    return (_countAvailableMoves(board, myPieces) -
            _countAvailableMoves(board, opponentPieces)) *
        10;
  }

  static int _countAvailableMoves(
    BoardState board,
    Iterable<Position> pieces,
  ) {
    var mobility = 0;
    for (final pos in pieces) {
      final adjacent = pos.getAdjacentPositions();
      for (final adj in adjacent) {
        if (board.getPiece(adj) == PieceType.empty) {
          mobility++;
        }
      }
    }
    return mobility;
  }

  /// Counts actual capture opportunities using the authoritative detector.
  static int _evaluateThreats(BoardState board, PieceType player) {
    final opportunities = GameEngine().getCaptureOpportunities(board, player);
    return opportunities.values.fold<int>(
          0,
          (total, destinations) => total + destinations.length,
        ) *
        200;
  }

  static int _evaluateDefense(BoardState board, PieceType player) =>
      -_evaluateThreats(board, player.getOpponent());
}
